/**
 * GarminCSVParser – Parser českého exportu Activities.csv z Garmin Connect
 * Řeší specifika českého formátu:
 * 1) Desetinné čárky u běhu/kola/chůze (např. "23,22" -> 23.22 km)
 * 2) Tečky jako oddělovače tisíců u plavání a veslování, kde je vzdálenost v metrech
 *    (např. "1.075" -> 1075 m = 1.075 km; "100" -> 100 m = 0.100 km; "9.511" -> 9511 m = 9.511 km)
 * 3) Časy s desetinami vteřin s čárkou i tečkou ("00:08:34,7", "02:32:39.3")
 * 4) Prázdné hodnoty "--", "--:--:--" a záporná čísla s apostrofem ("'-1", "'-285")
 * 5) Oddělení aktivity "Chůze" mimo hlavní triatlonový SBR objem (s přepínačem v UI)
 */

window.GarminCSVParser = (function () {
  /**
   * Rozparsuje jeden řádek CSV podle RFC 4180 (uvozovky, čárky uvnitř polí)
   */
  function parseCSVLine(line) {
    const result = [];
    let current = "";
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === '"') {
        if (inQuotes && line[i + 1] === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = !inQuotes;
        }
      } else if (ch === "," && !inQuotes) {
        result.push(current.trim());
        current = "";
      } else {
        current += ch;
      }
    }
    result.push(current.trim());
    return result;
  }

  /**
   * Vyčistí textovou hodnotu z Garmin CSV (odstraní uvozovky, apostrofy u záporných čísel, "--")
   */
  function cleanRawValue(val) {
    if (val === undefined || val === null) return "";
    let s = String(val).trim();
    if (s.startsWith('"') && s.endsWith('"')) {
      s = s.slice(1, -1).trim();
    }
    if (s.startsWith("'-")) {
      s = s.slice(1); // "'-27" -> "-27"
    }
    if (s === "--" || s === "--:--:--" || s === "") {
      return "";
    }
    return s;
  }

  /**
   * Obecný převod českého čísla z Garminu (např. "3.670" kcal -> 3670, "0,92" -> 0.92)
   */
  function parseGarminNumber(raw, isIntegerWithThousandsDot = false) {
    const s = cleanRawValue(raw);
    if (!s) return null;
    if (isIntegerWithThousandsDot) {
      // Např. Kalorie "3.670", Kroky "46.586", Výstup "1.038"
      const normalized = s.replace(/\./g, "").replace(",", ".");
      const n = parseFloat(normalized);
      return Number.isFinite(n) ? n : null;
    }
    // Pokud obsahuje tečku i čárku, tečka je tisícovka a čárka desetinná
    if (s.includes(".") && s.includes(",")) {
      const n = parseFloat(s.replace(/\./g, "").replace(",", "."));
      return Number.isFinite(n) ? n : null;
    }
    // Pokud obsahuje čárku, jde o desetinnou čárku ("23,22" -> 23.22)
    if (s.includes(",")) {
      const n = parseFloat(s.replace(",", "."));
      return Number.isFinite(n) ? n : null;
    }
    // Pokud obsahuje tečku u celočíselných metrik (např. "1.038"), řeší volající
    const n = parseFloat(s);
    return Number.isFinite(n) ? n : null;
  }

  /**
   * Speciální převod vzdálenosti podle typu aktivity:
   * - Plavání ("Plav. v bazénu", "Plavání ve volné vodě") a "Veslování" mají v českém Garminu
   *   vzdálenost v METRECH s tečkou jako oddělovačem tisíců ("1.075" = 1075 m = 1.075 km, "100" = 100 m = 0.1 km).
   * - Ostatní aktivity (Běh, Cyklistika, Chůze, Multisport...) mají vzdálenost v KILOMETRECH s desetinnou čárkou ("23,22" = 23.22 km).
   */
  function parseDistanceKm(rawDist, activityType) {
    const s = cleanRawValue(rawDist);
    if (!s) return 0;
    const typeLower = (activityType || "").toLowerCase();
    const isMetersActivity =
      typeLower.includes("plav") ||
      typeLower.includes("vesl") ||
      typeLower.includes("swim") ||
      typeLower.includes("row");

    if (isMetersActivity) {
      // V českém Garmin CSV: "1.000" -> 1000 m, "1.075" -> 1075 m, "9.511" -> 9511 m, "100" -> 100 m, "52" -> 52 m
      const metersStr = s.replace(/\./g, "").replace(",", ".");
      const meters = parseFloat(metersStr);
      if (!Number.isFinite(meters)) return 0;
      return meters / 1000;
    }

    // Standardní kilometrové aktivity ("42,74" -> 42.74 km, "113,60" -> 113.6 km)
    const kmStr = s.replace(/\./g, "").replace(",", ".");
    const km = parseFloat(kmStr);
    return Number.isFinite(km) ? km : 0;
  }

  /**
   * Převod času "HH:MM:SS", "HH:MM:SS,d" nebo "HH:MM:SS.d" na sekundy
   */
  function parseDurationSec(rawTime) {
    const s = cleanRawValue(rawTime);
    if (!s) return 0;
    const normalized = s.replace(",", ".");
    const parts = normalized.split(":").map(Number);
    if (parts.some((p) => !Number.isFinite(p))) return 0;
    if (parts.length === 3) {
      return parts[0] * 3600 + parts[1] * 60 + parts[2];
    }
    if (parts.length === 2) {
      return parts[0] * 60 + parts[1];
    }
    return 0;
  }

  /**
   * Klasifikace typu aktivity z českého Garmin Connectu do kategorií aplikace
   */
  function classifyActivity(rawType) {
    const t = (rawType || "").trim();
    const tl = t.toLowerCase();

    if (tl.includes("plav")) {
      return {
        discipline: "swim",
        label: "Plavání",
        isSBR: true,
        isWalk: false,
        isTriCore: true
      };
    }
    if (tl.includes("cykl") || tl.includes("kolo") || tl.includes("bike")) {
      return {
        discipline: "bike",
        label: "Kolo",
        isSBR: true,
        isWalk: false,
        isTriCore: true
      };
    }
    if (tl.includes("multisport") || tl.includes("triatlon")) {
      return {
        discipline: "multisport",
        label: "Triatlon / Multisport",
        isSBR: true,
        isWalk: false,
        isTriCore: true
      };
    }
    if (tl.includes("běh") && !tl.includes("lyž")) {
      return {
        discipline: "run",
        label: "Běh",
        isSBR: true,
        isWalk: false,
        isTriCore: true
      };
    }
    if (
      tl.includes("silový") ||
      tl.includes("síla") ||
      tl.includes("hiit") ||
      tl.includes("kardio") ||
      tl.includes("jóga") ||
      tl.includes("dech") ||
      tl.includes("eliptický")
    ) {
      return {
        discipline: "strength",
        label: "Síla / Kompenzace",
        isSBR: false,
        isWalk: false,
        isTriCore: true
      };
    }
    if (tl.includes("chůze") || tl.includes("turistika")) {
      return {
        discipline: "walk",
        label: "Chůze / Trek",
        isSBR: false,
        isWalk: true,
        isTriCore: false
      };
    }
    // Veslování, běžecké lyžování, inline bruslení, volejbal...
    return {
      discipline: "other",
      label: "Ostatní sport (" + t + ")",
      isSBR: false,
      isWalk: false,
      isTriCore: true
    };
  }

  /**
   * Najde index týdne T01–T48 (1..48), do kterého spadá dané ISO datum YYYY-MM-DD
   */
  function findPlanWeekNumber(isoDate, planWeeks) {
    if (!isoDate || !Array.isArray(planWeeks)) return null;
    for (let i = 0; i < planWeeks.length; i++) {
      const w = planWeeks[i];
      if (isoDate >= w.startDate && isoDate <= w.endDate) {
        return w.week;
      }
    }
    return null;
  }

  /**
   * Hlavní metoda: rozparsuje kompletní CSV text z Garmin Connectu
   */
  function parseCSV(csvText, planWeeks = window.PLAN_DATA ? window.PLAN_DATA.weeks : []) {
    if (!csvText || typeof csvText !== "string") {
      return { activities: [], summary: null, byWeek: {}, errors: ["Prázdný CSV vstup"] };
    }

    const cleanText = csvText.replace(/^\uFEFF/, "").trim();
    const lines = cleanText.split(/\r?\n/).filter((l) => l.trim().length > 0);
    if (lines.length < 2) {
      return { activities: [], summary: null, byWeek: {}, errors: ["CSV neobsahuje žádné datové řádky"] };
    }

    const headers = parseCSVLine(lines[0]);
    const colIdx = {};
    headers.forEach((h, idx) => {
      colIdx[h.trim()] = idx;
    });

    const getCol = (row, name) => {
      const idx = colIdx[name];
      return idx !== undefined && idx < row.length ? row[idx] : "";
    };

    const activities = [];
    const errors = [];

    for (let i = 1; i < lines.length; i++) {
      try {
        const row = parseCSVLine(lines[i]);
        if (row.length < 5) continue;

        const rawType = cleanRawValue(getCol(row, "Typ aktivity"));
        const rawDate = cleanRawValue(getCol(row, "Datum")); // "2026-10-23 06:01:55"
        const isoDate = rawDate ? rawDate.slice(0, 10) : "";
        const title = cleanRawValue(getCol(row, "Název")) || rawType;

        const distanceKm = parseDistanceKm(getCol(row, "Vzdálenost"), rawType);
        const durationSec = parseDurationSec(getCol(row, "Čas"));
        const durationHours = durationSec / 3600;

        const avgHr = parseGarminNumber(getCol(row, "Průměrný ST"));
        const maxHr = parseGarminNumber(getCol(row, "Maximální ST"));
        const avgPace = cleanRawValue(getCol(row, "Průměrné tempo"));
        const avgPower = parseGarminNumber(getCol(row, "Průměrný výkon"));
        const normPower = parseGarminNumber(getCol(row, "Normalized Power® (NP®)"));
        const elevationGainM = parseGarminNumber(getCol(row, "Celkový výstup"), true);
        const calories = parseGarminNumber(getCol(row, "Kalorie (kcal)"), true);
        const aerobicTe = parseGarminNumber(getCol(row, "Aerobní TE"));

        const category = classifyActivity(rawType);
        const weekNum = findPlanWeekNumber(isoDate, planWeeks);

        activities.push({
          id: `act-${i}-${isoDate}`,
          rowNumber: i + 1,
          rawType,
          discipline: category.discipline,
          categoryLabel: category.label,
          isSBR: category.isSBR,
          isWalk: category.isWalk,
          isTriCore: category.isTriCore,
          dateTime: rawDate,
          date: isoDate,
          title,
          distanceKm,
          distanceMeters: Math.round(distanceKm * 1000),
          durationSec,
          durationMin: Math.round((durationSec / 60) * 10) / 10,
          durationHours,
          avgHr,
          maxHr,
          avgPace,
          avgPower,
          normPower,
          elevationGainM,
          calories,
          aerobicTe,
          week: weekNum // null pokud je před 16. 11. 2026 (historický baseline)
        });
      } catch (err) {
        errors.push(`Řádek ${i + 1}: ${err.message}`);
      }
    }

    const summary = computeSummary(activities, planWeeks);
    return {
      activities,
      summary,
      byWeek: summary.byWeek,
      errors
    };
  }

  /**
   * Spočítá souhrnné statistiky (historický baseline + plnění týdnů T01–T48)
   */
  function computeSummary(activities, planWeeks = []) {
    const totals = {
      allCount: activities.length,
      sbrHours: 0,
      sbrKm: 0,
      triTotalHoursExclWalk: 0,
      walkCount: 0,
      walkHours: 0,
      walkKm: 0,
      byDiscipline: {
        swim: { count: 0, hours: 0, km: 0, meters: 0, avgHrSum: 0, avgHrCount: 0 },
        bike: { count: 0, hours: 0, km: 0, avgHrSum: 0, avgHrCount: 0, avgPowerSum: 0, avgPowerCount: 0 },
        run: { count: 0, hours: 0, km: 0, avgHrSum: 0, avgHrCount: 0 },
        strength: { count: 0, hours: 0, km: 0, avgHrSum: 0, avgHrCount: 0 },
        multisport: { count: 0, hours: 0, km: 0 },
        other: { count: 0, hours: 0, km: 0 },
        walk: { count: 0, hours: 0, km: 0 }
      },
      historicalCount: 0,
      inPlanCount: 0,
      dateMin: null,
      dateMax: null
    };

    const byWeek = {};
    planWeeks.forEach((w) => {
      byWeek[w.week] = {
        week: w.week,
        code: w.code,
        plannedHours: w.hours.total,
        actualHoursExclWalk: 0,
        actualHoursInclWalk: 0,
        swimHours: 0,
        swimMeters: 0,
        bikeHours: 0,
        bikeKm: 0,
        runHours: 0,
        runKm: 0,
        strengthHours: 0,
        walkHours: 0,
        walkKm: 0,
        activities: []
      };
    });

    activities.forEach((a) => {
      if (a.date) {
        if (!totals.dateMin || a.date < totals.dateMin) totals.dateMin = a.date;
        if (!totals.dateMax || a.date > totals.dateMax) totals.dateMax = a.date;
      }

      const dBucket = totals.byDiscipline[a.discipline] || totals.byDiscipline.other;
      dBucket.count += 1;
      dBucket.hours += a.durationHours;
      dBucket.km += a.distanceKm;
      if (a.discipline === "swim") {
        dBucket.meters += a.distanceMeters;
      }
      if (a.avgHr && dBucket.avgHrSum !== undefined) {
        dBucket.avgHrSum += a.avgHr;
        dBucket.avgHrCount += 1;
      }
      if (a.avgPower && dBucket.avgPowerSum !== undefined) {
        dBucket.avgPowerSum += a.avgPower;
        dBucket.avgPowerCount += 1;
      }

      if (a.isSBR) {
        totals.sbrHours += a.durationHours;
        totals.sbrKm += a.distanceKm;
      }
      if (!a.isWalk) {
        totals.triTotalHoursExclWalk += a.durationHours;
      } else {
        totals.walkCount += 1;
        totals.walkHours += a.durationHours;
        totals.walkKm += a.distanceKm;
      }

      if (a.week && byWeek[a.week]) {
        totals.inPlanCount += 1;
        const bw = byWeek[a.week];
        bw.activities.push(a);
        bw.actualHoursInclWalk += a.durationHours;
        if (!a.isWalk) {
          bw.actualHoursExclWalk += a.durationHours;
        }
        if (a.discipline === "swim") {
          bw.swimHours += a.durationHours;
          bw.swimMeters += a.distanceMeters;
        } else if (a.discipline === "bike" || a.discipline === "multisport") {
          bw.bikeHours += a.durationHours;
          bw.bikeKm += a.distanceKm;
        } else if (a.discipline === "run") {
          bw.runHours += a.durationHours;
          bw.runKm += a.distanceKm;
        } else if (a.discipline === "strength" || a.discipline === "other") {
          bw.strengthHours += a.durationHours;
        } else if (a.discipline === "walk") {
          bw.walkHours += a.durationHours;
          bw.walkKm += a.distanceKm;
        }
      } else {
        totals.historicalCount += 1;
      }
    });

    return {
      ...totals,
      byWeek
    };
  }

  return {
    parseCSVLine,
    parseDistanceKm,
    parseDurationSec,
    classifyActivity,
    parseCSV,
    computeSummary
  };
})();

